"""Read the accent ramp generated by Windows; never write personalization settings."""
from dataclasses import dataclass
import sys


@dataclass(frozen=True)
class AccentPalette:
    base: str = '#0078d4'
    dark_fill: str = '#60cdff'
    light_fill: str = '#0067c0'
    dark_text: str = '#99ebff'
    light_text: str = '#003e92'

    def fill(self, dark):
        return self.dark_fill if dark else self.light_fill

    def text(self, dark):
        return self.dark_text if dark else self.light_text


def _read_palette_bytes():
    if sys.platform != 'win32':
        return None
    import winreg
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER,
                r'Software\Microsoft\Windows\CurrentVersion\Explorer\Accent') as key:
            data, kind = winreg.QueryValueEx(key, 'AccentPalette')
        if kind == winreg.REG_BINARY and isinstance(data, bytes) and len(data) >= 28:
            return data
    except OSError:
        pass
    return None


def read_accent_palette():
    # Windows stores Light3, Light2, Light1, Accent, Dark1, Dark2, Dark3 as RGBx.
    # These values were cross-checked against UISettings.GetColorValue on Windows.
    data = _read_palette_bytes()
    if not isinstance(data, bytes) or len(data) < 28:
        return AccentPalette()
    colors = ['#' + data[i:i + 3].hex() for i in range(0, 28, 4)]
    return AccentPalette(base=colors[3], dark_fill=colors[1], light_fill=colors[4],
                         dark_text=colors[0], light_text=colors[5])
